    <td><?= $r['last_reviewed'] ? e(local_date((string) $r['last_reviewed'])) : '—' ?><form method="post" action="/admin/compliance/integrations/<?= e($r['id']) ?>/reviewed" class="inline-form"><?= csrf_field() ?><button class="btn btn-ghost btn-sm" type="submit">Reviewed today</button></form></td>
    <td><a href="/admin/compliance/integrations/<?= e($r['id']) ?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div></div>
